-- 011_soa_test_evaluation_iso27001_nov2025.sql
--
-- Carga como evaluacion de prueba en dev la data real de
-- "FM03-GPP_GC Declaracion de aplicabilidad del SGSI (SoA)_10.11.2025.xlsx" (carpeta
-- data de prueba) -- ISO 27001, los 93 controles del Anexo A con Aplicable/Implementado/
-- Nivel de madurez/Justificacion real, para poder probar dashboard, SOA, brechas, etc.
-- con data realista en vez de vacia.
--
-- Al revisar el archivo se resolvio tambien el pendiente de "94 vs 93 controles ISO 27001":
-- la celda A109 del Excel (fila en blanco despues del ultimo control, 8.34) tiene un
-- fragmento de texto suelto que parece resto de una justificacion mal pegada, no un
-- control 94 real. Los 93 controles calzan exacto con los ya cargados en MAE_CONTROL.
--
-- Solo carga MAE_CONTROL_EVALUATION (Anexo A) -- el Excel no trae data de las clausulas
-- (Requisitos 4-10), asi que esas quedan "Pendiente" en esta evaluacion, como cualquier
-- evaluacion real recien empezada.
--
-- Responsable (N_RESPONSIBLE_ID_FK) fijo en el usuario 1 (Anthony, cuenta personal de dev) para
-- toda la carga -- el Excel no trae un responsable por control, es NOT NULL en la tabla.
-- OJO antes de correr esto en producción: N_USER_ID_PK=1 es la cuenta de dev, puede no existir
-- (o ser otra persona) en producción. Revisar/cambiar este id por un responsable real de ONPE
-- antes de aplicar el script ahí -- no se resuelve solo, a diferencia del id de evaluación.
--
-- Probado en DB de desarrollo (Railway). Pendiente de aplicar en produccion -- el usuario pidio
-- explicitamente incluirla (es data real de evaluacion, no data ficticia de relleno). El insert
-- de MAE_EVALUATION busca el id recien creado por descripcion en vez de asumir uno fijo, asi que
-- corre igual en produccion aunque los ids autoincrementales no coincidan con los de dev.

BEGIN;

INSERT INTO "MAE_EVALUATION"
  ("D_START_DATE", "D_END_DATE", "C_DESCRIPTION", "N_STANDARD_ID_FK", "N_COMPANY_ID_FK",
   "D_CREATION_DATE", "N_CREATION_USER_ID", "N_IS_DELETED", "N_EVALUATION_STATE_ID_FK",
   "N_IS_GAP_ANALYSIS", "N_IS_CURRENT")
VALUES
  ('2025-11-01', '2025-11-30', 'Evaluación - Noviembre 2025 (SoA data de prueba)', 4, 1,
   now(), 1, false, 2, true, false);

-- Toma el id recien insertado sin asumir un numero fijo (evita pisar otra evaluacion si
-- este script se corre despues de que se hayan creado mas evaluaciones).
DO $$
DECLARE
  v_evaluation_id integer;
BEGIN
  SELECT "N_EVALUATION_ID_PK" INTO v_evaluation_id
  FROM "MAE_EVALUATION"
  WHERE "C_DESCRIPTION" = 'Evaluación - Noviembre 2025 (SoA data de prueba)' AND "N_STANDARD_ID_FK" = 4
  ORDER BY "N_EVALUATION_ID_PK" DESC LIMIT 1;

  INSERT INTO "MAE_CONTROL_EVALUATION"
    ("N_EVALUATION_ID_FK", "N_CONTROL_ID_FK", "N_MATURITY_LEVEL_ID_FK", "N_VALUE",
     "N_RESPONSIBLE_ID_FK", "C_JUSTIFICATION", "C_IMPROVEMENT_ACTIONS", "C_CONTROL_DESCRIPTION",
     "C_CONTROL_TYPE", "N_STANDARD_ID_FK", "N_COMPANY_ID_FK", "D_CREATION_DATE",
     "N_CREATION_USER_ID", "N_IS_DELETED")
  VALUES
    (v_evaluation_id, 2, 15, 4.00, 1, 'Es necesario para establecer directrices claras para proteger la información en toda la organización y alinearlas con los objetivos estratégicos.', '', 'Se debe definir un conjunto de políticas para la seguridad de la información, aprobada por la alta dirección, publicada y comunicada a los servidores y partes externas pertinentes; y revisadas a intervalos planificados y si ocurren cambios significativos.', 'Preventivo', 4, 1, now(), 1, false), -- 5.1
    (v_evaluation_id, 3, 15, 4.00, 1, 'Es necesario para definir claramente las funciones y responsabilidades, evitando ambigüedades y mejorando la gestión de la seguridad.', '', 'Se deben definir  y asignar de acuerdo con las necesidades de la organización  todas los roles y responsabilidades de la seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 5.2
    (v_evaluation_id, 4, 10, 3.00, 1, 'Es necesario para reducir el riesgo de fraude o errores al separar funciones críticas y evitar conflictos de interés.', '', 'Se debe separar Los deberes y áreas de responsabilidad en conflicto para reducir las posibilidades de modificación no autorizada o no intencional, o el uso indebido de los activos de la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 5.3
    (v_evaluation_id, 5, 10, 3.00, 1, 'Es necesario para asegurar el compromiso de la alta dirección con la seguridad de la información, asignando recursos y liderazgo.', '', 'La Alta Dirección debe exigir a todos los empleados y contratistas la aplicación de la seguridad de la información de acuerdo con las políticas y procedimientos establecidos por la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 5.4
    (v_evaluation_id, 7, 10, 3.00, 1, 'Es necesario para facilitar la comunicación con autoridades regulatorias en caso de incidentes o requisitos legales.', '', 'Se debe mantener los contactos apropiados con las autoridades pertinentes.', 'Preventivo y Correctivo', 4, 1, now(), 1, false), -- 5.5
    (v_evaluation_id, 8, 10, 3.00, 1, 'Es necesario para mantenerse actualizado sobre amenazas, vulnerabilidades y mejores prácticas a través de redes de colaboración.', '', 'Se debe mantener contactos apropiados con grupos de interés especial u otros foros y asociaciones profesionales especializadas en seguridad.', 'Preventivo', 4, 1, now(), 1, false), -- 5.6
    (v_evaluation_id, 9, 14, 2.00, 1, 'Es necesario para anticipar riesgos mediante la recopilación y análisis de información sobre amenazas relevantes.', '', 'Se debe recopilar y analizar información relacionada con las amenazas a la seguridad de la información', 'Preventivo', 4, 1, now(), 1, false), -- 5.7
    (v_evaluation_id, 10, 14, 2.00, 1, 'Es necesario para incorporar requisitos de seguridad desde la fase de planificación y ejecución de proyectos.', '', 'Se debe integrar La seguridad de la información en la gestión de proyectos para garantizar que los riesgos de seguridad de la información se abordan como parte de la gestión del proyecto.', 'Preventivo', 4, 1, now(), 1, false), -- 5.8
    (v_evaluation_id, 11, 14, 2.00, 1, 'Es necesario para identificar, clasificar y gestionar todos los activos que soportan la seguridad de la información.', '', 'Se debe desarrollar y mantener un inventario de información y otros activos asociados, incluidos los propietarios.', 'Preventivo', 4, 1, now(), 1, false), -- 5.9
    (v_evaluation_id, 12, 14, 2.00, 1, 'Es necesario para definir normas de uso responsable de la información y recursos tecnológicos.', '', 'Se debe identificar, documentar e implementar reglas para el uso aceptable y procedimientos para el manejo de la información y otros activos asociados.', 'Preventivo', 4, 1, now(), 1, false), -- 5.10
    (v_evaluation_id, 13, 10, 3.00, 1, 'Es necesario para garantizar la devolución de todos los activos al finalizar una relación laboral o contractual.', '', 'Todos los empleados y usuarios de partes externas deben devolver todos los activos de la organización que se encuentren a su cargo, al terminar su empleo, contrato o acuerdo.', 'Preventivo', 4, 1, now(), 1, false), -- 5.11
    (v_evaluation_id, 14, 14, 2.00, 1, 'Es necesario para asignar niveles de protección adecuados según la criticidad y sensibilidad de la información.', '', 'Se debe clasificar la información de acuerdo con las necesidades de seguridad de la información de la ONPE en función de la confidencialidad, integridad, disponibilidad y los requisitos de las partes interesadas pertinentes.', 'Preventivo', 4, 1, now(), 1, false), -- 5.12
    (v_evaluation_id, 15, 14, 2.00, 1, 'Es necesario para identificar visualmente la clasificación de la información y facilitar su manejo seguro.', '', 'Se debe desarrollar e implementar un conjunto adecuado de procedimientos para el etiquetado de la información, de acuerdo con el esquema de clasificación de información adoptado por la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 5.13
    (v_evaluation_id, 16, 14, 2.00, 1, 'Es necesario para proteger la confidencialidad e integridad de la información durante su transmisión interna o externa.', '', 'Se debe contar con políticas, procedimientos o acuerdos de transferencia  de información en todo tipo de instalaciones de transferencia dentro de la organización  y entre la organización y otras partes.', 'Preventivo', 4, 1, now(), 1, false), -- 5.14
    (v_evaluation_id, 17, 14, 2.00, 1, 'Es necesario para asegurar que solo personal autorizado acceda a sistemas y datos según el principio de mínimo privilegio.', '', 'Se debe establecer e implementar reglas para controlar el acceso físico y lógico a la información y otros activos asociados en función de los requisitos de negocio y de seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 5.15
    (v_evaluation_id, 18, 10, 3.00, 1, 'Es necesario para administrar de forma segura el ciclo de vida de las identidades digitales en los sistemas de la organización.', '', 'Se debe gestionar el ciclo de vida completo de las identidades', 'Preventivo', 4, 1, now(), 1, false), -- 5.16
    (v_evaluation_id, 19, 10, 3.00, 1, 'Es necesario para proteger credenciales y datos de autenticación contra accesos no autorizados.', '', 'Se debe controlar la asignación y gestión de la información de autenticación mediante un proceso de gestión, incluido el asesoramiento al personal sobre el manejo adecuado de la información de autenticación.', 'Preventivo', 4, 1, now(), 1, false), -- 5.17
    (v_evaluation_id, 20, 14, 2.00, 1, 'Es necesario para definir y revisar periódicamente los derechos de acceso a la información y sistemas críticos.', '', 'Se debe proporcionar, revisar, modificar y eliminar de acuerdo con las políticas y procedimientos de control de acceso de la organización los derechos de acceso a la información y otros activos asociados.', 'Preventivo', 4, 1, now(), 1, false), -- 5.18
    (v_evaluation_id, 21, 10, 3.00, 1, 'Es necesario para garantizar que los proveedores apliquen controles adecuados para proteger la información.', '', 'Se debe definir e implementar procesos y procedimientos para gestionar los riesgos de seguridad de la información asociados con el uso de productos o servicios de terceros', 'Preventivo', 4, 1, now(), 1, false), -- 5.19
    (v_evaluation_id, 22, 10, 3.00, 1, 'Es necesario para incluir explícitamente requisitos de seguridad en los contratos y acuerdos de servicio.', '', 'Se debe establecer y acordar con cada proveedor en función del tipo de relación con el proveedor los requisitos de seguridad de la información pertinentes', 'Preventivo', 4, 1, now(), 1, false), -- 5.20
    (v_evaluation_id, 23, 10, 3.00, 1, 'Es necesario para asegurar que los riesgos en la cadena de suministro de TIC estén controlados.', '', 'Se debe definir e implementar procesos y procedimientos para gestionar los riesgos de seguridad de la información asociados con la cadena de suministros de productos y servicios de TIC.', 'Preventivo', 4, 1, now(), 1, false), -- 5.21
    (v_evaluation_id, 24, 10, 3.00, 1, 'Es necesario para monitorear que los proveedores mantengan los niveles de seguridad acordados durante todo el servicio.', '', 'Se debe monitorear, revisar, evaluar y gestionar periódicamente los cambios en las practicas de seguridad de la información del proveedor y la prestación de servicios', 'Preventivo', 4, 1, now(), 1, false), -- 5.22
    (v_evaluation_id, 25, 14, 2.00, 1, 'Es necesario para proteger la información almacenada o procesada en servicios cloud.', '', 'Se debe establecer procesos de adquisición, uso, gestión y salida de los servicios en nube de acuerdo con los requisitos de seguridad de la información de la Entidad.', 'Preventivo', 4, 1, now(), 1, false), -- 5.23
    (v_evaluation_id, 26, 14, 2.00, 1, 'Es necesario para contar con procesos definidos y recursos para gestionar incidentes de forma eficaz.', '', 'Se debe planificar y preparar la gestión de incidentes de seguridad de la información definiendo, estableciendo y comunicando procesos, funciones y responsabilidades de gestión de incidentes de seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 5.24
    (v_evaluation_id, 27, 14, 2.00, 1, 'Es necesario para distinguir entre eventos y verdaderos incidentes de seguridad para priorizar la respuesta.', '', 'Se debe evaluar los incidentes de seguridad de la información y decidir si se van a clasificar como incidentes de seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 5.25
    (v_evaluation_id, 28, 14, 2.00, 1, 'Es necesario para contener, erradicar y recuperar ante incidentes de seguridad.', '', 'Se debe responder  a los incidentes de seguridad de la información de acuerdo con procedimientos documentados.', 'Preventivo', 4, 1, now(), 1, false), -- 5.26
    (v_evaluation_id, 29, 14, 2.00, 1, 'Es necesario para mejorar continuamente mediante las lecciones aprendidas de incidentes.', '', 'Se debe utilizar el conocimiento obtenido de los incidentes de seguridad de la información para fortalecer y mejorar los controles de seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 5.27
    (v_evaluation_id, 30, 14, 2.00, 1, 'Es necesario para preservar evidencia válida para análisis forense o procesos legales.', '', 'Se debe establecer e implementar  procedimientos para la identificación, recopilación, adquisición y preservación de evidencia relacionada con eventos de seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 5.28
    (v_evaluation_id, 31, 14, 2.00, 1, 'Es necesario para garantizar que la información permanezca protegida incluso durante interrupciones operativas.', '', 'Se debe planificar como mantener la seguridad de la información a un nivel adecuado durante la interrupción.', 'Preventivo', 4, 1, now(), 1, false), -- 5.29
    (v_evaluation_id, 32, 14, 2.00, 1, 'Es necesario para asegurar que las TIC soporten los requisitos de continuidad y recuperación.', '', 'La preparación de las TIC se  debe planificar, implementar, mantener y probar en función de los objetivos de continuidad de negocio y requisito de continuidad de las TIC.', 'Preventivo', 4, 1, now(), 1, false), -- 5.30
    (v_evaluation_id, 33, 10, 3.00, 1, 'Es necesario para asegurar el cumplimiento de todas las obligaciones aplicables.', '', 'Se debe identificar, documentar y mantener actualizados los requisitos legales, estatutarios, reglamentarios y contractuales relevantes para la seguridad de la información y el enfoque de la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 5.31
    (v_evaluation_id, 34, 10, 3.00, 1, 'Es necesario para proteger el uso legítimo de software, documentación y contenido intelectual.', '', 'Se debe implementar procedimientos apropiados para proteger los derechos de propiedad intelectual.', 'Preventivo', 4, 1, now(), 1, false), -- 5.32
    (v_evaluation_id, 35, 14, 2.00, 1, 'Es necesario para asegurar la integridad, disponibilidad y confidencialidad de los registros importantes.', '', 'Se debe proteger los registros contra perdida, destrucción, falsificación, acceso no autorizado y publicación no autorizada.', 'Preventivo', 4, 1, now(), 1, false), -- 5.33
    (v_evaluation_id, 36, 10, 3.00, 1, 'Es necesario para cumplir con las normativas de protección de datos personales y evitar incidentes de privacidad.', '', 'Se debe identificar y cumplir los requisitos relacionados con la preservación de la privacidad  y la protección de la PII de acuerdo con las leyes y reglamentos aplicables y los requisitos contractuales.', 'Preventivo', 4, 1, now(), 1, false), -- 5.34
    (v_evaluation_id, 37, 15, 4.00, 1, 'Es necesario para validar la eficacia de los controles mediante auditorías independientes.', '', 'Se debe revisar de forma independiente  a intervalos planificados o cuando ocurran cambios significativos el enfoque de la organización para gestionar la seguridad de la información y su implementación.', 'Preventivo y Correctivo', 4, 1, now(), 1, false), -- 5.35
    (v_evaluation_id, 38, 10, 3.00, 1, 'Es necesario para garantizar que las políticas y reglas de seguridad se apliquen de manera uniforme.', '', 'Se debe revisar periódicamente el cumplimiento de la política y normas de seguridad de la información de la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 5.36
    (v_evaluation_id, 39, 10, 3.00, 1, 'Es necesario para estandarizar y asegurar las operaciones, reduciendo errores y omisiones.', '', 'Los procedimientos  operativos para las instalaciones de procesamiento de información se deben documentar y  poner a disposición del personal que los necesita.', 'Preventivo', 4, 1, now(), 1, false), -- 5.37
    (v_evaluation_id, 1, 10, 3.00, 1, 'Es necesario para verificar la idoneidad del personal antes de su contratación, reduciendo riesgos internos a la seguridad de la información.', '', 'Las verificaciones de los antecedentes de todos los candidatos a un empleo en la organización, se deben llevar a cabo de acuerdo con las leyes, reglamentos y ética pertinentes, y deben ser proporcionales a los requisitos de negocio, a la clasificación de la información a que se va a tener acceso, y a los riesgos percibidos.', 'Preventivo', 4, 1, now(), 1, false), -- 6.1
    (v_evaluation_id, 6, 10, 3.00, 1, 'Es necesario para asegurar que los empleados comprendan sus responsabilidades en materia de seguridad de la información desde el inicio de la relación laboral.', '', 'Se debe establecer en los acuerdos contractuales de empleo las responsabilidades del personal y de la organización para la seguridad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 6.2
    (v_evaluation_id, 40, 15, 4.00, 1, 'Es necesario para garantizar que todo el personal conozca las políticas, procedimientos y buenas prácticas de seguridad, reduciendo errores humanos.', '', 'Todos los empleados de la organización y las partes interesadas relevantes  deben recibir la formación en toma de conciencia, educación y capacitación adecuadas  en seguridad de la información y actualizaciones regulares sobre las políticas y procedimientos pertinentes para su cargo.', 'Preventivo', 4, 1, now(), 1, false), -- 6.3
    (v_evaluation_id, 41, 15, 4.00, 1, 'Es necesario para establecer consecuencias claras ante incumplimientos de las políticas de seguridad, reforzando la cultura de protección de la información.', '', 'Se debe contar con un proceso disciplinario formal el cual debería ser comunicado, para emprender acciones contra empleados que hayan cometido una violación a la seguridad de la información.', 'Preventivo y Correctivo', 4, 1, now(), 1, false), -- 6.4
    (v_evaluation_id, 42, 10, 3.00, 1, 'Es necesario para asegurar que los accesos sean revocados y se mantenga la confidencialidad de la información tras la finalización o cambio de funciones.', '', 'Se deben definir, aplicarse y comunicarse al personal pertinente y otras partes interesadas las responsabilidades y los deberes de seguridad de la información que permanecen validos después de la terminación o cambio de contrato o empleo.', 'Preventivo', 4, 1, now(), 1, false), -- 6.5
    (v_evaluation_id, 43, 10, 3.00, 1, 'Es necesario para garantizar que los empleados, contratistas y terceros protejan la información sensible y no la divulguen sin autorización.', '', 'Se debe identificar,  documentar, revisar regularmente los requisitos para los acuerdos de confidencialidad o no divulgación que reflejen las necesidades de la organización para la protección de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 6.6
    (v_evaluation_id, 44, 10, 3.00, 1, 'Es necesario para proteger la información y los activos tecnológicos cuando se accede o procesa desde ubicaciones remotas fuera de las instalaciones.', '', 'Se debe implementar  medidas de seguridad cuando el personal trabaja de forma remota para proteger la información a la que se accede o almacena fuera de las instalaciones de la Entidad.', 'Preventivo', 4, 1, now(), 1, false), -- 6.7
    (v_evaluation_id, 45, 10, 3.00, 1, 'Es necesario para asegurar que todos los usuarios conozcan cómo reportar eventos o debilidades de seguridad de manera oportuna.', '', 'Se debe proporcionar un mecanismo para que el personal informe eventos de seguridad de la información observados o sospechados a través de los canales apropiados de manera oportuna', 'Preventivo', 4, 1, now(), 1, false), -- 6.8
    (v_evaluation_id, 46, 15, 4.00, 1, 'Es necesario para proteger las instalaciones contra accesos no autorizados y amenazas externas, reduciendo riesgos a las áreas críticas.', '', 'Se debe definir perímetros de seguridad  y usarlos para proteger áreas que contengan información sensible o critica y otros activos asociados', 'Preventivo', 4, 1, now(), 1, false), -- 7.1
    (v_evaluation_id, 47, 15, 4.00, 1, 'Es necesario para garantizar que solo personal autorizado pueda ingresar a áreas donde se maneja información sensible.', '', 'Se deben proteger las áreas seguras con controles de entrada y puntos de acceso apropiados', 'Preventivo', 4, 1, now(), 1, false), -- 7.2
    (v_evaluation_id, 48, 15, 4.00, 1, 'Es necesario para proteger físicamente las áreas donde se procesa o almacena información crítica.', '', 'Se debe diseñar y aplicar seguridad física a oficinas, salas e instalaciones.', 'Preventivo', 4, 1, now(), 1, false), -- 7.3
    (v_evaluation_id, 49, 10, 3.00, 1, 'Es necesario para detectar y responder a eventos físicos anómalos que puedan afectar la seguridad de la información.', '', 'Se debe monitorear continuamente las instalaciones para detectar accesos físicos no autorizados', 'Preventivo', 4, 1, now(), 1, false), -- 7.4
    (v_evaluation_id, 50, 10, 3.00, 1, 'Es necesario para salvaguardar las instalaciones y activos frente a desastres naturales, incendios u otras amenazas ambientales.', '', 'Se debe diseñar e implementar la protección contra amenazas físicas y ambientales, como  desastres naturales, y otras amenazas físicas intencionales o no intencionales a la infraestructura.', 'Preventivo', 4, 1, now(), 1, false), -- 7.5
    (v_evaluation_id, 51, 10, 3.00, 1, 'Es necesario para garantizar que las operaciones en áreas críticas se realicen bajo controles adecuados, protegiendo la información procesada.', '', 'Se debe diseñar y aplicar medidas de seguridad para trabajar en áreas seguras.', 'Preventivo', 4, 1, now(), 1, false), -- 7.6
    (v_evaluation_id, 52, 10, 3.00, 1, 'Es necesario para evitar que información confidencial quede expuesta en escritorios físicos o pantallas sin supervisión.', '', 'Se debe  adoptar una política de escritorio limpio para los documentos y medios de almacenamiento removibles, y una política de pantalla limpia en las instalaciones de procesamiento de información.', 'Preventivo', 4, 1, now(), 1, false), -- 7.7
    (v_evaluation_id, 53, 15, 4.00, 1, 'Es necesario para asegurar que los equipos sean ubicados en lugares protegidos contra riesgos ambientales, robos o daños físicos.', '', 'Se debe ubicar y proteger los equipos de forma segura', 'Preventivo', 4, 1, now(), 1, false), -- 7.8
    (v_evaluation_id, 54, 10, 3.00, 1, 'Es necesario para proteger los activos que se utilizan fuera de las instalaciones de la organización.', '', 'Se debe aplicar medidas de seguridad a los activos que se encuentran fuera de las instalaciones de la organización, teniendo en cuenta los diferentes riesgos de trabajar fuera de  instalaciones.', 'Preventivo', 4, 1, now(), 1, false), -- 7.9
    (v_evaluation_id, 56, 10, 3.00, 1, 'Es necesario para proteger la información contenida en medios físicos durante su uso, transporte y desecho.', '', 'Se debe gestionar los medios de almacenamiento a lo largo de su ciclo de vida de adquisición, uso, transporte y eliminación de acuerdo con el esquema de clasificación y los requisitos de manipulación de la entidad.', 'Preventivo', 4, 1, now(), 1, false), -- 7.10
    (v_evaluation_id, 55, 10, 3.00, 1, 'Es necesario para asegurar que servicios como electricidad, climatización o redes mantengan su disponibilidad y confiabilidad.', '', 'Se debe proteger las instalaciones de procesamiento de información contra cortes de energía y otras interrupciones causadas por falla en los servicios de suministro', 'Preventivo y Detectivo', 4, 1, now(), 1, false), -- 7.11
    (v_evaluation_id, 57, 10, 3.00, 1, 'Es necesario para proteger el cableado contra accesos no autorizados, interferencias o sabotajes.', '', 'Se debe proteger los cables que transportan energía, datos o servicios de información de apoyo contra intercepciones, interferencias o daños.', 'Preventivo', 4, 1, now(), 1, false), -- 7.12
    (v_evaluation_id, 58, 10, 3.00, 1, 'Es necesario para asegurar que el mantenimiento de los equipos se realice de forma controlada y sin comprometer la seguridad de la información.', '', 'Se debe mantener correctamente los equipos  para garantizar su disponibilidad, integridad y confidencialidad de la información.', 'Preventivo', 4, 1, now(), 1, false), -- 7.13
    (v_evaluation_id, 59, 15, 4.00, 1, 'Es necesario para eliminar de forma segura la información residual antes de la disposición o reutilización de equipos, evitando fugas de datos.', '', 'Se debe verificar todos los elementos de equipos que contengan medios de almacenamiento, para garantizar que cualquier dato sensible o software con licencia haya sido retirado o sobrescrito en forma segura antes de su disposición o reutilización.', 'Preventivo', 4, 1, now(), 1, false), -- 7.14
    (v_evaluation_id, 60, 15, 4.00, 1, 'Es necesario para proteger los dispositivos finales que procesan información crítica, garantizando su confidencialidad, integridad y disponibilidad.', '', 'Se debe proteger la información almacenada,  procesada o accesible a través de los dispositivos finales de los usuarios.', 'Preventivo', 4, 1, now(), 1, false), -- 8.1
    (v_evaluation_id, 61, 14, 2.00, 1, 'Es necesario para controlar y supervisar el uso de cuentas privilegiadas, reduciendo el riesgo de accesos indebidos y garantizando trazabilidad.', '', 'Se debe restringir y controlar la asignación y uso de derechos de acceso privilegiado.', 'Preventivo', 4, 1, now(), 1, false), -- 8.2
    (v_evaluation_id, 62, 10, 3.00, 1, 'Es necesario para asegurar que la información esté disponible solo para personas autorizadas, evitando accesos no deseados.', '', 'Se debe restringir el acceso a la información y otros activos asociados de acuerdo con la política de control de acceso', 'Preventivo', 4, 1, now(), 1, false), -- 8.3
    (v_evaluation_id, 63, 10, 3.00, 1, 'Es necesario para proteger la integridad del código fuente y evitar modificaciones no autorizadas que comprometan la seguridad.', '', 'Se debería Controlar el acceso de lectura y escritura  a los códigos fuente de los programas, las herramientas de desarrollo y las bibliotecas de software.', 'Preventivo', 4, 1, now(), 1, false), -- 8.4
    (v_evaluation_id, 64, 10, 3.00, 1, 'Es necesario para garantizar que solo usuarios legítimos accedan a los sistemas, fortaleciendo la protección frente a suplantaciones de identidad.', '', 'Se debe implementar tecnologías y procedimientos de autenticación seguros en función de las restricciones de acceso a la información y la política de control de acceso.', 'Preventivo', 4, 1, now(), 1, false), -- 8.5
    (v_evaluation_id, 65, 10, 3.00, 1, 'Es necesario para asegurar la disponibilidad de los servicios tecnológicos frente a la demanda actual y futura.', '', 'Se debe monitorear y ajustar el uso de recursos de acuerdo con los requisitos de capacidad actuales y esperados', 'Preventivo y Detectivo', 4, 1, now(), 1, false), -- 8.6
    (v_evaluation_id, 66, 15, 4.00, 1, 'Es necesario para prevenir, detectar y responder a amenazas de malware que comprometan la operación de los sistemas.', '', 'Se debe implementar controles de detección, de prevención y de recuperación, combinados con la toma de conciencia apropiada de los usuarios, para proteger contra códigos maliciosos.', 'Preventivo, Detectivo y Correctivo', 4, 1, now(), 1, false), -- 8.7
    (v_evaluation_id, 67, 15, 4.00, 1, 'Es necesario para identificar y mitigar vulnerabilidades a tiempo, reduciendo la posibilidad de explotación por atacantes.', '', 'Se debe obtener oportunamente información acerca de las vulnerabilidades técnicas de los sistemas de información que se usen; evaluar la exposición de la organización a estas vulnerabilidades, y tomar las medidas apropiadas para tratar el riesgo asociado.', 'Preventivo', 4, 1, now(), 1, false), -- 8.8
    (v_evaluation_id, 68, 14, 2.00, 1, 'Es necesario para asegurar que las configuraciones de sistemas sean consistentes y seguras, reduciendo errores y brechas de seguridad.', '', 'Se debe establecer, documentar, implementar, monitorear y revisar las configuraciones, incluidas las configuraciones de seguridad, hardware, software, servicios y redes.', 'Preventivo', 4, 1, now(), 1, false), -- 8.9
    (v_evaluation_id, 69, 15, 4.00, 1, 'Es necesario para garantizar la destrucción segura de información que ya no es requerida, evitando fugas de datos.', '', 'Se debe eliminar cuando ya no sea necesaria la información almacenada  en sistemas de información, dispositivos o en cualquier otro medio', 'Preventivo', 4, 1, now(), 1, false), -- 8.10
    (v_evaluation_id, 70, 10, 3.00, 1, 'Es necesario para proteger datos sensibles en entornos de prueba o desarrollo, evitando su exposición innecesaria.', '', 'Debe utilizarse de acuerdo con la política específica de la organización sobre control de acceso, otras políticas específicas relacionadas y los requisitos del negocio, teniendo en cuenta la legislación aplicable.', 'Preventivo', 4, 1, now(), 1, false), -- 8.11
    (v_evaluation_id, 71, 10, 3.00, 1, 'Es necesario para evitar la exfiltración no autorizada de información confidencial mediante controles de monitoreo y filtrado.', '', 'Se debe aplicar medidas de prevención de fuga de datos a los sistemas, redes y cualquier otro dispositivo que procese, almacene o transmita información confidencial.', 'Preventivo y Correctivo', 4, 1, now(), 1, false), -- 8.12
    (v_evaluation_id, 72, 10, 3.00, 1, 'Es necesario para garantizar la recuperación oportuna de la información ante incidentes, fallos o desastres.', '', 'Se debe mantener y probar regularmente las copias de respaldo de la información, el software y los sistemas de acuerdo con la política de respaldo establecida.', 'Preventivo', 4, 1, now(), 1, false), -- 8.13
    (v_evaluation_id, 73, 15, 4.00, 1, 'Es necesario para asegurar la continuidad operativa mediante infraestructuras redundantes ante fallas críticas.', '', 'Las instalaciones de procesamiento de información se deben implementar con redundancia suficiente para cumplir los requisitos de disponibilidad.', 'Preventivo', 4, 1, now(), 1, false), -- 8.14
    (v_evaluation_id, 74, 14, 2.00, 1, 'Es necesario para disponer de trazabilidad y evidencia en auditorías, investigaciones y análisis de incidentes.', '', 'Se debe producir, almacenar, proteger, y analizar registros (eventos) que registren actividades, excepciones, fallas y otros eventos relevantes.', 'Preventivo', 4, 1, now(), 1, false), -- 8.15
    (v_evaluation_id, 75, 10, 3.00, 1, 'Es necesario para detectar comportamientos anómalos e incidentes de seguridad en tiempo oportuno.', '', 'Se deben monitorear las redes, los sistemas y las aplicaciones para detectar comportamientos anómales y deben tomarse las medidas apropiadas para evaluar posibles incidentes de seguridad de la información.', 'Detectivo y Correctivo', 4, 1, now(), 1, false), -- 8.16
    (v_evaluation_id, 76, 10, 3.00, 1, 'Es necesario para mantener registros coherentes y precisos en todos los sistemas, facilitando auditorías y análisis forenses.', '', 'Se deben sincronizar con las fuentes de tiempo aprobadas  todos los relojes de los sistemas de procesamiento de información utilizados por la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 8.17
    (v_evaluation_id, 77, 15, 4.00, 1, 'Es necesario para controlar el uso de herramientas que puedan modificar sistemas críticos, evitando accesos indebidos.', '', 'Se debe restringir y controlar estrictamente el uso de programas utilitarios que podrían ser capaces de anular los controles del sistema y de las aplicaciones.', 'Preventivo', 4, 1, now(), 1, false), -- 8.18
    (v_evaluation_id, 78, 15, 4.00, 1, 'Es necesario para asegurar que solo se instale software autorizado y confiable, reduciendo riesgos de malware o incompatibilidades.', '', 'Se debe implementar procedimientos y medidas para gestionar de forma segura las instalación de software en los sistemas operativos.', 'Preventivo', 4, 1, now(), 1, false), -- 8.19
    (v_evaluation_id, 79, 15, 4.00, 1, 'Es necesario para proteger la red contra amenazas externas e internas, garantizando comunicaciones seguras.', '', 'Se debe proteger, administrar y controlar las redes y los dispositivos de red para salvaguardar la información en los sistemas y aplicaciones.', 'Preventivo y Detectivo', 4, 1, now(), 1, false), -- 8.20
    (v_evaluation_id, 80, 10, 3.00, 1, 'Es necesario para mantener configuraciones seguras en servicios de red, evitando vulnerabilidades explotables.', '', 'Se debe identificar, implementar y monitorear  los mecanismos de seguridad, los niveles de servicio y los requisitos de gestión de todos los servicios de red.', 'Preventivo', 4, 1, now(), 1, false), -- 8.21
    (v_evaluation_id, 81, 10, 3.00, 1, 'Es necesario para aislar entornos críticos y limitar movimientos laterales de atacantes en caso de incidentes.', '', 'Se deben segregar en las redes de la organización los grupos de servicios de información, usuarios y sistemas de información.', 'Preventivo', 4, 1, now(), 1, false), -- 8.22
    (v_evaluation_id, 82, 14, 2.00, 1, 'Es necesario para controlar el acceso a contenidos maliciosos o no relacionados con las funciones laborales.', '', 'Se debe gestionar el acceso a sitios web externos para reducir la exposición a contenido malicioso.', 'Preventivo', 4, 1, now(), 1, false), -- 8.23
    (v_evaluation_id, 83, 10, 3.00, 1, 'Es necesario para proteger la confidencialidad e integridad de la información durante su almacenamiento y transmisión.', '', 'Se debe definir e implementar las reglas para el uso eficaz de la criptografía, incluida la gestión de claves  criptográficas.', 'Preventivo', 4, 1, now(), 1, false), -- 8.24
    (v_evaluation_id, 84, 10, 3.00, 1, 'Es necesario para integrar buenas prácticas de seguridad en todas las fases del desarrollo de software.', '', 'Se debe establecer y aplicar reglas para el desarrollo seguro de software y de sistemas dentro de la organización.', 'Preventivo', 4, 1, now(), 1, false), -- 8.25
    (v_evaluation_id, 85, 14, 2.00, 1, 'Es necesario para definir y validar medidas de seguridad desde el diseño de las aplicaciones.', '', 'Se debe identificar, especificar  y aprobar los requisitos de seguridad de la información al desarrollar o adquirir aplicaciones.', 'Preventivo', 4, 1, now(), 1, false), -- 8.26
    (v_evaluation_id, 86, 15, 4.00, 1, 'Es necesario para construir sistemas resilientes mediante principios de seguridad como defensa en profundidad.', '', 'Se deben establecer, documentar, mantener y aplicar a cualquier actividad de desarrollo de sistemas de información  principios para el diseño de sistemas seguros .', 'Preventivo', 4, 1, now(), 1, false), -- 8.27
    (v_evaluation_id, 87, 14, 2.00, 1, 'Es necesario para evitar vulnerabilidades comunes durante el desarrollo de aplicaciones.', '', 'Se debe aplicar al desarrollo de software principios de codificación segura.', 'Preventivo', 4, 1, now(), 1, false), -- 8.28
    (v_evaluation_id, 88, 10, 3.00, 1, 'Es necesario para garantizar que los sistemas sean evaluados y reforzados antes de su puesta en producción.', '', 'Se deben definir e implementar en el ciclo de vida del desarrollo procesos de prueba de seguridad.', 'Preventivo', 4, 1, now(), 1, false), -- 8.29
    (v_evaluation_id, 89, 12, 0.00, 1, 'No aplica porque la institución no subcontrata el desarrollo de aplicaciones o sistemas, ya que son realizados in-house.', '', 'Se debe dirigir, monitorear y revisar las actividades relacionadas con el desarrollo de sistemas contratados externamente.', 'Preventivo y Detectivo', 4, 1, now(), 1, false), -- 8.30
    (v_evaluation_id, 90, 15, 4.00, 1, 'Es necesario para evitar que los cambios en desarrollo o pruebas afecten la estabilidad del entorno productivo.', '', 'Se debe separar y proteger los entornos de desarrollo, prueba y producción.', 'Preventivo', 4, 1, now(), 1, false), -- 8.31
    (v_evaluation_id, 91, 10, 3.00, 1, 'Es necesario para evaluar, autorizar y documentar los cambios, reduciendo riesgos de fallos o incidentes.', '', 'Se debe definir, establecer e implementar procedimientos de gestión de cambios para controlar los cambios en las instalaciones de procesamiento de información y los sistemas de información .', 'Preventivo', 4, 1, now(), 1, false), -- 8.32
    (v_evaluation_id, 92, 10, 3.00, 1, 'Es necesario para proteger la confidencialidad de datos reales en ambientes de prueba.', '', 'La información de prueba se debe seleccionar, proteger y controlar cuidadosamente.', 'Preventivo', 4, 1, now(), 1, false), -- 8.33
    (v_evaluation_id, 93, 10, 3.00, 1, 'Es necesario para asegurar que las auditorías no comprometan la disponibilidad ni la seguridad de los sistemas.', '', 'Se debe planificar y acordar entre el evaluador y la gerencia correspondiente las pruebas de auditoria y otras actividades de aseguramiento que involucren la evaluación de los sistemas operativos.', 'Preventivo', 4, 1, now(), 1, false); -- 8.34
END $$;

COMMIT;

-- Verificacion post-ejecucion
SELECT e."N_EVALUATION_ID_PK", e."C_DESCRIPTION", count(ce."N_CONTROL_EVALUATION_ID_PK") as controles_cargados
FROM "MAE_EVALUATION" e
JOIN "MAE_CONTROL_EVALUATION" ce ON ce."N_EVALUATION_ID_FK" = e."N_EVALUATION_ID_PK"
WHERE e."C_DESCRIPTION" = 'Evaluación - Noviembre 2025 (SoA data de prueba)' AND e."N_STANDARD_ID_FK" = 4
GROUP BY e."N_EVALUATION_ID_PK", e."C_DESCRIPTION";
